When a function reaches areturnstatement, the functionstops executing.

Thevalueafter thereturnkeywordis sent backto the caller.

Most functions return the result of a calculation or an operation.

The returned value can be used anywhere a value is expected.

You can use a function call inside another expression.

A function can return any type of value (not only numbers).

Code written after areturnstatement willNOT be executed.

If a function does not return a value, the return value will beundefined.

You can usereturnto stop a function early, based on a condition.

Returned function values are often used to update HTML content.

### Code Snippets

```
function sayHello() {
return "Hello World";
}
let message = sayHello();

---

function multiply(a, b) {
return a * b;
}
let result = multiply(4, 5);

---

function multiply(a, b) {
return a * b;
}
let total = multiply(2, 3) * 10;

---

function fullName(firstName, lastName) {
return firstName + " " + lastName;
}
let name = fullName("John", "Doe");

---

function multiply(a, b) {
return "Done";
// Next line will never run
return a * b;
}
let result = multiply(4, 3);

---

function multiply(a, b) {
let x = a * b;
}
let result = multiply(4, 3);

---

function checkAge(age) {
if (age < 18) {
return "Too young";
}
return "Access granted";
}

